{
  "ContractVersion": "v0.2",
  "Status": "WORKING_CONTENT_CONTRACT",
  "Название": "Девять кейсов для роли Специалист эксперт с конкретизацией по контексту участника",
  "Назначение": "Содержательные входы и ограничения для сборщика, LLM-генератора и тестера. Не задаёт API, имена полей продуктового хранилища или язык предикатов.",
  "Согласовано": "Одна BaseRole specialist_expert; профессиональное содержание, включая аргумент и показатель, меняется по контексту в пределах функций Case. Цена в Case02 необязательна. Прежнее отложенное решение о расширении цены закрыто текущим указанием пользователя.",
  "Входы": [
    {
      "Объект": "Выбранный Case",
      "Требование": "Полный текущий паспорт, CaseID/Version, CT, точные IndicatorIDs/версии М2, все инварианты, материалы и события. Старые запреты из истории не объединять с новой версией."
    },
    {
      "Объект": "PersonalizedProfile",
      "Требование": "Зафиксированный допустимый OrganizationContext + RoleProfile + UserContext и их версии. Роль специалиста, область, типовые задачи, объект ответственности и мандат; существенные противоречия не скрывать."
    },
    {
      "Объект": "Программа",
      "Требование": "Бюджет и режим программы, разрешённые Case и правила M7. В текущем замысле 120 минут и продолжение сохранённой AS; не менять это на обязательное предъявление всех девяти."
    },
    {
      "Объект": "Авторские примеры",
      "Требование": "Использовать для понимания конструкции и контрпримеров, не как неизменяемый Sales-текст, список разрешённых профессий или образец правильного ответа."
    }
  ],
  "Этапы": [
    {
      "Шаг": 1,
      "Название": "Проверить применимость",
      "Действие": "Отобразить рабочие функции Case на достаточный контекст деятельности. Отличить отсутствующую косметику от неизвестного мандата. Наличие готового реального эпизода не требуется.",
      "Выход": "Основание применимости; точный существенный пробел для уточнения; либо причина выбрать другой Case по M7. Не оценка уровня."
    },
    {
      "Шаг": 2,
      "Название": "Построить функциональное соответствие",
      "Действие": "Для каждого инварианта и переменного параметра определить реализацию в профессиональном контексте, источники профиля и связанные места изменения.",
      "Выход": "Закрытая карта функций и замен. Пример: один выгодный признак → плановое число откликов; независимые требования → условия профиля и срок. Карта не предъявляется участнику."
    },
    {
      "Шаг": 3,
      "Название": "Создать полную AS",
      "Действие": "Согласованно создать P00, задание, все документы, авторство, персонажей, знания, полномочия, фиксированные факты, события, реакции и завершение. Явно отделить учебные условия от фактов организации.",
      "Выход": "Полная версия AS с публичным и закрытым составом; без ответов участника, Evidence, IA и уровней."
    },
    {
      "Шаг": 4,
      "Название": "Выполнить формальную проверку",
      "Действие": "Сверить ссылки и версии, 22 поля Case, цели, уникальные ID, состав материалов, аудитории, полноту событий, числовые отношения и разделение публичного/закрытого.",
      "Выход": "PASS/FAIL по фактическим проверкам с файлами, путями и значениями. Функциональную эквивалентность эта проверка не доказывает."
    },
    {
      "Шаг": 5,
      "Название": "Выполнить содержательную проверку",
      "Действие": "По каждому инварианту и условию IndicatorID сопоставить конкретные фрагменты AS и отношения между ними. Проверить потерю противоречия, готовую подсказку, фиктивный вклад, расширение мандата, чуждый предмет, случайную несогласованность и изменение нагрузки.",
      "Выход": "Обоснованные находки тестера: фрагмент, правило, дефект/основание и действие. Нельзя ставить PASS лишь потому, что генератор написал «сохранено». При неустранённом существенном дефекте AS не предъявлять."
    },
    {
      "Шаг": 6,
      "Название": "Исправить и зафиксировать",
      "Действие": "Исправить все зависимые части; повторить затронутые проверки. Если функция несовместима с ролью, уточнить контекст или выбрать другой Case. Ограничить цикл исправлений технической настройкой; не показывать дефектный fallback.",
      "Выход": "Сохранённая AS и зафиксированные версии профиля, Case, правил, генератора и проверок. Число попыток и схема хранения — решение архитектора."
    },
    {
      "Шаг": 7,
      "Название": "Провести и продолжить после паузы",
      "Действие": "Предъявлять материалы и отклики по смысловым условиям, аудитории и мандату. Сохранять знания, события и собственные согласия. На возврате использовать ту же AS; не регенерировать её.",
      "Выход": "Фактическая траектория для M6/M7. Конец сценария и AS_close различаются; новых Turns после AS_close нет."
    }
  ],
  "Правила": [
    {
      "RuleID": "G01",
      "Правило": "Case задаёт функциональную оценочную конструкцию и точные цели М2. AS создаётся целиком по зафиксированному профилю. Sales и альтернативные авторские AS — примеры, не разрешённый список профессий."
    },
    {
      "RuleID": "G02",
      "Правило": "Проверять соответствие деятельности, объекту ответственности и мандату. Название должности помогает ориентироваться, но не доказывает применимость. Не отказывать лишь из-за отсутствия профессии в примерах; сначала попытаться отобразить функции Case на подтверждённые задачи."
    },
    {
      "RuleID": "G03",
      "Правило": "Необходимость уточнения или другого Case возникает при невозможности сохранить функцию, подтверждённом конфликте с ролью либо нехватке существенного контекста. Косметические пробелы допускают нейтральные учебные значения."
    },
    {
      "RuleID": "G04",
      "Правило": "Сохранять CT, точные IndicatorIDs, формат и число активных персонажей, отношения между вкладами, границы знания, источник противоречия и открытость исхода. Профессиональные слова, показатели и предметы могут меняться внутри этих функций."
    },
    {
      "RuleID": "G05",
      "Правило": "ФИО и контакты реального участника не нужны для сюжета. Учебные имена, числа, события и документы фиксируются как синтетические; не приписывать их реальной организации. Пол и формы обращения влияют только на согласованность текста, не на механизм, сложность или оценку."
    },
    {
      "RuleID": "G06",
      "Правило": "Каждая замена проводится во всех зависимых местах: P00, задания, документы, авторы, персонажи, закрытые факты, полномочия, события, реакции, завершение, наблюдаемость и QA. Нельзя менять только вводную или сохранять чуждые профессии детали ради старого текста."
    },
    {
      "RuleID": "G07",
      "Правило": "Сохранять информационную нагрузку: число сравниваемых вариантов/вкладов, независимые ограничения, расхождение, неполноту и необходимость собственного решения. Значения чисел не являются инвариантами; отношения между ними проверяются."
    },
    {
      "RuleID": "G08",
      "Правило": "Не превращать функциональное обобщение в произвольный новый сюжет. Если нельзя сохранить хотя бы одно обязательное условие наблюдения, вернуть AS на исправление или выбрать другой применимый Case; цели не менять под созданный текст."
    },
    {
      "RuleID": "G09",
      "Правило": "Формальный валидатор проверяет целостность, ссылки, аудитории, арифметику и версии. Содержательный тестер проверяет функцию каждого инварианта по конкретным фрагментам. Наличие метки invariant_id само по себе не является PASS."
    },
    {
      "RuleID": "G10",
      "Правило": "LLM возвращает проверяемое основание, обнаруженный дефект или неопределённость. Уверенность модели и хороший стиль текста не заменяют проверки; не создавать Evidence, IA, уровни или фиктивное прохождение до взаимодействия."
    },
    {
      "RuleID": "G11",
      "Правило": "Правила прекращения, паузы и знания обязательны для любого профессионального предмета. После возврата продолжается та же сохранённая AS и профиль; не генерировать новый текст и не повторять уже предъявленное событие."
    },
    {
      "RuleID": "G12",
      "Правило": "Девять — состав каталога одной BaseRole specialist_expert. Бюджет программы 120 минут не означает обязательного предъявления всех девяти. Другие BaseRole и мини-кейсы в этот выпуск не входят."
    },
    {
      "RuleID": "G13",
      "Правило": "Анкета не обязана содержать готовый сюжет, все документы или подтверждение того, что человек уже попадал в подобный эпизод. По достаточным сведениям о деятельности, задачах и мандате создаётся типичная учебная ситуация. Её события, числа и имена синтетические; подтверждённые ограничения организации не отменяются."
    }
  ],
  "Поля содержательного выхода": [
    "Ссылка Case и версия",
    "Ссылка профиля и версии составляющих",
    "Основание применимости по деятельности",
    "Карта функциональных замен и зависимостей",
    "Полные открытые и закрытые материалы",
    "Персонажи и их знания/мандат",
    "События с условиями, эффектом, повтором и запретом",
    "Точная карта каждого IndicatorID на конкретные условия",
    "Реестр проверок и нерешённых дефектов",
    "Учебное происхождение событий и чисел"
